import io, hashlib, json
from pathlib import Path
from dataclasses import replace
from unittest.mock import patch
import numpy as np
from training.holistic_migration import dataset as d
from training.holistic_migration.tests.test_sequence import frames
p = Path('/Users/ahronjanl.rafaelahron.0804icloudcom/.hermes/cache/scratch/task-c-review-memory-only.npz')
assert not p.exists()
stored = {}
original_open, original_load, original_sha = Path.open, np.load, d.sha256
class MemoryWrite(io.BytesIO):
    def __exit__(self, *args):
        stored['bytes'] = self.getvalue()
        self.close()
def opened(path, mode='r', *args, **kwargs):
    if path == p:
        assert mode == 'xb'
        return MemoryWrite()
    return original_open(path, mode, *args, **kwargs)
def loaded(path, *args, **kwargs):
    if isinstance(path, Path) and path == p:
        path = io.BytesIO(stored['bytes'])
    return original_load(path, *args, **kwargs)
def checksum(path):
    return hashlib.sha256(stored['bytes']).hexdigest() if path == p else original_sha(path)
with patch.object(Path, 'open', opened), patch.object(np, 'load', loaded), patch.object(d, 'sha256', checksum):
    for dtype, value in [('int64', 2**63-1), ('uint64', 2**64-1)]:
        f = replace(frames()[0], face=np.array([[value, 0, 0]], dtype=dtype))
        digest = d.write_raw(p, [f])
        back = d.read_raw(p, digest)
        actual = int(back[0].face[0, 0])
        print(json.dumps({'dtype': dtype, 'input_integer': value, 'decoded_integer': actual, 'lossless': actual == value}))
        assert actual == value, 'lossless raw codec violation'
assert not p.exists()
